-- Package 1: no changes to event rows, attribution views or grants.
BEGIN;
DO $$ BEGIN
 IF NOT has_function_privilege('service_role','public.dashboard_snapshot(text,text,date,date,integer)','EXECUTE')
 OR has_function_privilege('anon','public.dashboard_snapshot(text,text,date,date,integer)','EXECUTE')
 OR has_function_privilege('authenticated','public.dashboard_snapshot(text,text,date,date,integer)','EXECUTE') THEN
 RAISE EXCEPTION 'Unexpected snapshot permissions: stop and review'; END IF;
END $$;
CREATE OR REPLACE FUNCTION public.dashboard_breakdowns(p_start_date date, p_end_date date, p_attribution_model text DEFAULT 'last'::text, p_limit integer DEFAULT 20) RETURNS jsonb LANGUAGE plpgsql STABLE AS $function$ DECLARE v_model text := LOWER( COALESCE( p_attribution_model, 'last' ) ); v_limit integer := GREATEST( 1, LEAST( COALESCE(p_limit, 20), 100 ) ); v_result jsonb; BEGIN IF v_model NOT IN ('first', 'last') THEN RAISE EXCEPTION 'p_attribution_model deve ser first ou last'; END IF; WITH base AS ( SELECT d.id, d.lead_id, d.visitor_id, d.clicked_at, CASE WHEN v_model = 'first' THEN d.first_channel_final ELSE d.last_channel_final END AS channel, CASE WHEN v_model = 'first' THEN d.first_attribution_confidence ELSE d.last_attribution_confidence END AS confidence, COALESCE( NULLIF( BTRIM( CASE WHEN v_model = 'first' THEN d.first_source_effective ELSE d.last_source_effective END ), '' ), 'No identificado' ) AS source, COALESCE( NULLIF( BTRIM( CASE WHEN v_model = 'first' THEN d.first_medium_effective ELSE d.last_medium_effective END ), '' ), 'No identificado' ) AS medium, COALESCE( NULLIF( BTRIM( CASE WHEN v_model = 'first' THEN d.first_campaign_effective ELSE d.last_campaign_effective END ), '' ), 'Sin campaña' ) AS campaign, COALESCE( NULLIF( BTRIM( CASE WHEN v_model = 'first' THEN d.first_content_effective ELSE d.last_content_effective END ), '' ), 'Sin anuncio / creativo' ) AS creative, CASE WHEN v_model = 'first' THEN d.first_keyword_safe ELSE d.last_keyword_safe END AS keyword, CASE WHEN v_model = 'first' THEN d.first_landing_semantic ELSE d.last_landing_semantic END AS landing_page, CASE WHEN v_model = 'first' THEN d.first_landing_quality ELSE d.last_landing_quality END AS landing_quality, COALESCE( NULLIF( BTRIM(d.page_url_clean), '' ), 'No identificada' ) AS click_page, COALESCE( NULLIF( BTRIM(d.click_text_normalized), '' ), 'No identificado' ) AS button, d.meta_campaign_id, d.meta_adset_id, d.meta_ad_id, d.meta_adset_name, d.meta_source, d.placement, d.google_campaign_id, d.google_adgroup_id, d.google_ad_id, d.google_target_id, d.matchtype_normalized, d.network_normalized, d.device_normalized FROM public.vw_whatsapp_leads_keywords_safe d WHERE d.is_valid_click = true AND d.is_test_record = false AND d.clicked_at >= ( p_start_date::timestamp AT TIME ZONE 'America/Santiago' ) AND d.clicked_at < LEAST(NOW(), (p_end_date + 1)::timestamp AT TIME ZONE 'America/Santiago') ), channels AS ( SELECT channel, COUNT(*) AS contacts FROM base GROUP BY channel ), confidence AS ( SELECT confidence, COUNT(*) AS contacts FROM base GROUP BY confidence ), sources AS ( SELECT channel, source, COUNT(*) AS contacts FROM base GROUP BY channel, source ), mediums AS ( SELECT channel, medium, COUNT(*) AS contacts FROM base GROUP BY channel, medium ), campaigns AS ( SELECT channel, campaign, confidence, COUNT(*) AS contacts FROM base GROUP BY channel, campaign, confidence ), creatives AS ( SELECT channel, campaign, creative, COUNT(*) AS contacts FROM base GROUP BY channel, campaign, creative ), keywords AS ( SELECT channel, campaign, keyword, COUNT(*) AS contacts FROM base WHERE keyword IS NOT NULL AND BTRIM(keyword) <> '' GROUP BY channel, campaign, keyword ), landing_pages AS ( SELECT landing_page, landing_quality, COUNT(*) AS contacts FROM base GROUP BY landing_page, landing_quality ), click_pages AS ( SELECT click_page, COUNT(*) AS contacts FROM base GROUP BY click_page ), buttons AS ( SELECT button, COUNT(*) AS contacts FROM base GROUP BY button ), devices AS ( SELECT device_normalized AS device, COUNT(*) AS contacts FROM base WHERE device_normalized IS NOT NULL GROUP BY device_normalized ), networks AS ( SELECT network_normalized AS network, COUNT(*) AS contacts FROM base WHERE network_normalized IS NOT NULL GROUP BY network_normalized ), matchtypes AS ( SELECT matchtype_normalized AS matchtype, COUNT(*) AS contacts FROM base WHERE matchtype_normalized IS NOT NULL GROUP BY matchtype_normalized ), meta_breakdown AS ( SELECT COALESCE( NULLIF(BTRIM(meta_source), ''), 'No identificado' ) AS source, COALESCE( NULLIF(BTRIM(placement), ''), 'No identificado' ) AS placement, COUNT(*) AS contacts FROM base WHERE channel = 'Meta Ads' GROUP BY COALESCE( NULLIF(BTRIM(meta_source), ''), 'No identificado' ), COALESCE( NULLIF(BTRIM(placement), ''), 'No identificado' ) ) SELECT jsonb_build_object( 'meta', jsonb_build_object( 'timezone', 'America/Santiago', 'start_date', p_start_date, 'end_date', p_end_date, 'attribution_model', v_model, 'valid_clicks', ( SELECT COUNT(*) FROM base ) ), 'channels', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'channel', x.channel, 'contacts', x.contacts ) ORDER BY x.contacts DESC, x.channel ) FROM ( SELECT * FROM channels ORDER BY contacts DESC, channel ) x ), '[]'::jsonb ), 'attribution_confidence', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'confidence', x.confidence, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM confidence x ), '[]'::jsonb ), 'sources', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'channel', x.channel, 'source', x.source, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM ( SELECT * FROM sources ORDER BY contacts DESC LIMIT v_limit ) x ), '[]'::jsonb ), 'mediums', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'channel', x.channel, 'medium', x.medium, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM ( SELECT * FROM mediums ORDER BY contacts DESC LIMIT v_limit ) x ), '[]'::jsonb ), 'campaigns', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'channel', x.channel, 'campaign', x.campaign, 'confidence', x.confidence, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM ( SELECT * FROM campaigns ORDER BY contacts DESC LIMIT v_limit ) x ), '[]'::jsonb ), 'creatives', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'channel', x.channel, 'campaign', x.campaign, 'creative', x.creative, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM ( SELECT * FROM creatives ORDER BY contacts DESC LIMIT v_limit ) x ), '[]'::jsonb ), 'keywords', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'channel', x.channel, 'campaign', x.campaign, 'keyword', x.keyword, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM ( SELECT * FROM keywords ORDER BY contacts DESC LIMIT v_limit ) x ), '[]'::jsonb ), 'landing_pages', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'page', x.landing_page, 'quality', x.landing_quality, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM ( SELECT * FROM landing_pages ORDER BY contacts DESC LIMIT v_limit ) x ), '[]'::jsonb ), 'click_pages', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'page', x.click_page, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM ( SELECT * FROM click_pages ORDER BY contacts DESC LIMIT v_limit ) x ), '[]'::jsonb ), 'buttons', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'button', x.button, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM ( SELECT * FROM buttons ORDER BY contacts DESC LIMIT v_limit ) x ), '[]'::jsonb ), 'devices', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'device', x.device, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM devices x ), '[]'::jsonb ), 'networks', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'network', x.network, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM networks x ), '[]'::jsonb ), 'matchtypes', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'matchtype', x.matchtype, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM matchtypes x ), '[]'::jsonb ), 'meta_placements', COALESCE( ( SELECT jsonb_agg( jsonb_build_object( 'source', x.source, 'placement', x.placement, 'contacts', x.contacts ) ORDER BY x.contacts DESC ) FROM ( SELECT * FROM meta_breakdown ORDER BY contacts DESC LIMIT v_limit ) x ), '[]'::jsonb ) ) INTO v_result; RETURN v_result; END; $function$;

CREATE OR REPLACE FUNCTION public.dashboard_snapshot(p_preset text DEFAULT '7d'::text, p_attribution_model text DEFAULT 'last'::text, p_custom_start date DEFAULT NULL::date, p_custom_end date DEFAULT NULL::date, p_limit integer DEFAULT 20) RETURNS jsonb LANGUAGE plpgsql STABLE AS $function$ DECLARE v_model text := LOWER( TRIM( COALESCE( p_attribution_model, 'last' ) ) ); v_limit integer := GREATEST( 1, LEAST( COALESCE(p_limit, 20), 100 ) ); v_period jsonb; v_start_date date; v_end_date date; v_kpis jsonb; v_breakdowns jsonb; v_campaigns jsonb; v_timeseries jsonb; v_comparisons jsonb; v_kpi_contacts bigint; v_breakdown_contacts bigint; v_timeseries_contacts bigint; v_campaign_contacts bigint; v_result jsonb; v_count jsonb; v_channel_sum bigint; v_daily_sum bigint; v_previous_available boolean; BEGIN IF v_model NOT IN ('first', 'last') THEN RAISE EXCEPTION 'p_attribution_model deve ser first ou last'; END IF; v_period := public.dashboard_resolve_period( p_preset, p_custom_start, p_custom_end ); v_start_date := (v_period ->> 'start_date')::date; v_end_date := (v_period ->> 'end_date')::date; v_kpis := public.dashboard_kpis( v_start_date, v_end_date, v_model ); v_breakdowns := public.dashboard_breakdowns( v_start_date, v_end_date, v_model, v_limit ); v_campaigns := public.dashboard_campaigns( v_start_date, v_end_date, v_model, v_limit ); v_timeseries := public.dashboard_timeseries( v_start_date, v_end_date, v_model ); v_comparisons := public.dashboard_comparisons( v_start_date, v_end_date, v_model );
IF jsonb_typeof(v_kpis->'current') IS DISTINCT FROM 'object'
 OR jsonb_typeof(v_kpis->'previous') IS DISTINCT FROM 'object'
 OR jsonb_typeof(v_kpis->'change') IS DISTINCT FROM 'object'
 OR jsonb_typeof(v_breakdowns->'channels') IS DISTINCT FROM 'array'
 OR jsonb_typeof(v_timeseries->'comparison') IS DISTINCT FROM 'array'
 OR jsonb_typeof(v_timeseries->'channels') IS DISTINCT FROM 'array'
 OR jsonb_typeof(v_campaigns->'campaigns') IS DISTINCT FROM 'array'
 OR jsonb_typeof(v_comparisons #> '{comparisons,previous_period,available}') NOT IN ('boolean','null')
 OR v_comparisons #> '{comparisons,previous_period,available}' IS NULL THEN
 RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Incomplete dashboard snapshot';
END IF;
FOR v_count IN
 SELECT value FROM jsonb_array_elements(jsonb_build_array(
 v_kpis #> '{current,valid_clicks}', v_breakdowns #> '{meta,valid_clicks}',
 v_timeseries #> '{totals,current_contacts}', v_campaigns->'total_campaign_contacts'))
 UNION ALL SELECT item->'contacts' FROM jsonb_array_elements(v_breakdowns->'channels') item
 UNION ALL SELECT item->'current_contacts' FROM jsonb_array_elements(v_timeseries->'comparison') item
LOOP
 IF jsonb_typeof(v_count) IS DISTINCT FROM 'number' OR (v_count #>> '{}') !~ '^[0-9]+$' THEN
  RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Missing or invalid dashboard count';
 END IF;
END LOOP;
SELECT COALESCE(SUM((item->>'contacts')::bigint),0) INTO v_channel_sum
 FROM jsonb_array_elements(v_breakdowns->'channels') item;
SELECT COALESCE(SUM((item->>'current_contacts')::bigint),0) INTO v_daily_sum
 FROM jsonb_array_elements(v_timeseries->'comparison') item;
v_previous_available := COALESCE((v_comparisons #>> '{comparisons,previous_period,available}')::boolean,false);
v_kpis := jsonb_set(v_kpis, '{period,previous_available}', to_jsonb(v_previous_available));
v_timeseries := jsonb_set(v_timeseries, '{meta,previous_available}', to_jsonb(v_previous_available));
IF NOT v_previous_available THEN
 v_kpis := jsonb_set(v_kpis, '{change}', jsonb_build_object('valid_clicks_pct',NULL,'google_ads_pct',NULL,'meta_ads_pct',NULL,'organic_pct',NULL));
 v_timeseries := jsonb_set(v_timeseries, '{totals,change_pct}', 'null'::jsonb);
 v_timeseries := jsonb_set(v_timeseries, '{comparison}',
  (SELECT COALESCE(jsonb_agg(jsonb_set(item, '{change_pct}', 'null'::jsonb) ORDER BY ordinal),'[]'::jsonb)
   FROM jsonb_array_elements(v_timeseries->'comparison') WITH ORDINALITY AS t(item,ordinal)));
END IF;
 v_kpi_contacts := COALESCE( ( v_kpis -> 'current' ->> 'valid_clicks' )::bigint, 0 ); v_breakdown_contacts := COALESCE( ( v_breakdowns -> 'meta' ->> 'valid_clicks' )::bigint, 0 ); v_timeseries_contacts := COALESCE( ( v_timeseries -> 'totals' ->> 'current_contacts' )::bigint, 0 ); v_campaign_contacts := COALESCE( ( v_campaigns ->> 'total_campaign_contacts' )::bigint, 0 ); v_result := jsonb_build_object( 'schema_version', '1.1', 'request', jsonb_build_object( 'preset', p_preset, 'attribution_model', v_model, 'custom_start', p_custom_start, 'custom_end', p_custom_end, 'limit', v_limit ), 'period', v_period, 'kpis', v_kpis, 'breakdowns', v_breakdowns, 'campaigns', v_campaigns, 'timeseries', v_timeseries, 'comparisons', v_comparisons, 'integrity', jsonb_build_object( 'kpi_valid_clicks', v_kpi_contacts, 'breakdown_valid_clicks', v_breakdown_contacts, 'timeseries_valid_clicks', v_timeseries_contacts, 'campaign_contacts', v_campaign_contacts, 'core_totals_match', ( v_kpi_contacts = v_breakdown_contacts AND v_kpi_contacts = v_timeseries_contacts AND v_kpi_contacts = v_channel_sum AND v_kpi_contacts = v_daily_sum ), 'campaign_coverage_rate', CASE WHEN v_kpi_contacts = 0 THEN 0 ELSE ROUND( ( v_campaign_contacts::numeric / v_kpi_contacts::numeric ) * 100, 2 ) END ) ); RETURN v_result; END; $function$;
COMMIT;
